INSERT INTO entry_resource_scans(entry_id,checked_at,source_url,wip_status,resource_listing_status,notes) SELECT id,'2026-09-15',COALESCE(wip,'https://boardgamegeek.com/geeklist/353866/2025-solomode-design-contest-submissions'),CASE WHEN wip IS NULL THEN 'not_found' ELSE 'found' END,status,CASE WHEN status='not_observable' THEN 'Risorsa dichiarata ma non più osservabile dal primo post.' WHEN status='not_checked' THEN 'La voce GeekList punta alla pagina generale del contest; nessun WIP individuale inventato.' WHEN status='none_declared' THEN 'Primo post letto integralmente: nessun collegamento pertinente osservato.' ELSE 'Primo post renderizzato censito; destinazioni non aperte.' END FROM sm_e;
INSERT INTO entry_resource_mentions(entry_id,remote_resource_id,source_url,label_raw,content_role,is_primary,first_seen_at,last_seen_at) SELECT r.entry_id,rr.id,s.wip,r.label,r.role,CASE WHEN r.role='game_files' THEN 1 ELSE 0 END,'2026-09-15','2026-09-15' FROM sm_r r JOIN sm_e s ON s.id=r.entry_id JOIN entries e ON e.id=r.entry_id JOIN remote_resources rr ON rr.game_id=e.game_id AND rr.url=r.url;
INSERT INTO remote_resource_observations(remote_resource_id,observed_at,evidence_url,observation_kind,availability_status,notes) SELECT rr.id,'2026-09-15',s.wip,'declared_in_wip','not_checked','Destinazione non aperta. Contesto: '||r.context FROM sm_r r JOIN sm_e s ON s.id=r.entry_id JOIN entries e ON e.id=r.entry_id JOIN remote_resources rr ON rr.game_id=e.game_id AND rr.url=r.url WHERE NOT EXISTS(SELECT 1 FROM remote_resource_observations o WHERE o.remote_resource_id=rr.id AND o.observed_at='2026-09-15');
INSERT INTO remote_resource_observations(remote_resource_id,observed_at,evidence_url,observation_kind,availability_status,notes) SELECT rr.id,'2026-09-15',e.wip_thread_url,'declared_in_wip','not_checked','Destinazione non aperta. Contesto: '||COALESCE((SELECT r.context FROM sm_r r WHERE r.entry_id=e.id AND r.url=rr.url),'vedere registro versionato') FROM entries e JOIN remote_resources rr ON rr.game_id=e.game_id WHERE e.contest_id=16 AND rr.first_seen_at='2026-09-15' AND NOT EXISTS(SELECT 1 FROM remote_resource_observations o WHERE o.remote_resource_id=rr.id AND o.observed_at='2026-09-15');
