-- Solomode 2025 first-post resources; external destinations were not opened.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TEMP TABLE sm_e(id PRIMARY KEY,title,wip,status);
CREATE TEMP TABLE sm_r(entry_id,url,role,form,label,context,PRIMARY KEY(entry_id,url));
UPDATE entries SET wip_thread_url=(SELECT wip FROM sm_e WHERE sm_e.id=entries.id) WHERE contest_id=16;
DELETE FROM entry_resource_scans WHERE entry_id IN (SELECT id FROM entries WHERE contest_id=16) AND checked_at='2026-09-15';
INSERT OR IGNORE INTO remote_resources(game_id,kind,access_type,url,host,label,availability_status,first_seen_at,last_verified_at) SELECT e.game_id,r.role,r.form,r.url,substr(r.url,instr(r.url,'//')+2,instr(substr(r.url,instr(r.url,'//')+2),'/')-1),r.label,'unknown','2026-09-15','2026-09-15' FROM sm_r r JOIN entries e ON e.id=r.entry_id;
DELETE FROM entry_resource_mentions WHERE entry_id IN (SELECT id FROM entries WHERE contest_id=16);
INSERT OR IGNORE INTO entry_resource_mentions(entry_id,remote_resource_id,source_url,label_raw,content_role,is_primary,first_seen_at,last_seen_at) SELECT e.id,rr.id,e.wip_thread_url,rr.label,rr.kind,CASE WHEN rr.kind='game_files' THEN 1 ELSE 0 END,'2026-09-15','2026-09-15' FROM entries e JOIN remote_resources rr ON rr.game_id=e.game_id WHERE e.contest_id=16 AND rr.first_seen_at='2026-09-15';
DROP TABLE sm_r;
DROP TABLE sm_e;
COMMIT;
